head.script:
scwin.onpageload = function() {
    selSelectYy.setValue("2022");
};
scwin.onpageunload = function() {};
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "1500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('selSelectYy_img').click()");
    WebSquare.wUnit.addCommand("pause", "1500");
    WebSquare.wUnit.addCommand("assert", "document.getElementsByClassName('w2calendar_picker_cell active')[0].innerText == '2022'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Created By: Sangwook
    //Created By: 2021.01.20
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
